class BowlingGame:
    def __init__(self):
        self.rolls = []

    def roll(self, pins):
        if pins < 0 or pins > 10:
            raise Exception(f"Rolling {pins} pins is not allowed")
        if self._game_over():
            raise Exception("Cannot roll after game is over")
        frame, i = self._current_frame()
        if frame < 9:
            if self.rolls[i] != 10 and self.rolls[i] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
        else:
            tenth = self.rolls[i:]
            if len(tenth) == 1 and tenth[0] < 10 and tenth[0] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
            if (
                len(tenth) == 2
                and tenth[0] == 10
                and tenth[1] < 10
                and tenth[1] + pins > 10
            ):
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points"
                )
        self.rolls.append(pins)

    def score(self):
        if not self._game_over():
            raise Exception("Cannot score an incomplete game")
        total = 0
        rolls = self.rolls
        i = 0
        for frame in range(10):
            if frame < 9:
                if rolls[i] == 10:
                    total += 10 + rolls[i + 1] + rolls[i + 2]
                    i += 1
                elif rolls[i] + rolls[i + 1] == 10:
                    total += 10 + rolls[i + 2]
                    i += 2
                else:
                    total += rolls[i] + rolls[i + 1]
                    i += 2
            else:
                total += sum(rolls[i:])
        return total

    def _current_frame(self):
        """Return (frame, index of the first roll in that frame), 0-based."""
        rolls = self.rolls
        i = 0
        for frame in range(10):
            if i >= len(rolls):
                return frame, i
            if frame < 9:
                i += 1 if rolls[i] == 10 else 2
            else:
                return 9, i
        return 10, len(rolls)

    def _game_over(self):
        return len(self.rolls) >= self._required_rolls()

    def _required_rolls(self):
        """Total number of rolls a complete game requires, given the rolls so far."""
        rolls = self.rolls
        i = 0
        total = 0
        for frame in range(10):
            if i >= len(rolls):
                total += 2 * (10 - frame)
                break
            if frame < 9:
                total += 1 if rolls[i] == 10 else 2
                i += 1 if rolls[i] == 10 else 2
            elif rolls[i] == 10:
                total += 3
                i += 3
            elif i + 1 < len(rolls) and rolls[i] + rolls[i + 1] == 10:
                total += 3
                i += 3
            else:
                total += 2
                i += 2
        return total

